using AtomBlazor.Primitives;
using System.Security.Cryptography;
using System.Text;
using AtomBlazor.Primitives.QrCode;
using Xunit;

namespace AtomBlazor.Tests.QrCode;

/// <summary>
/// 自 QrCode/QrEncoderGoldenTests.cs（七规则机械改名 →AtomBlazor、注释汉化；金样与断言字符串字面量逐字节保原样，方法名保英）。
/// <para>
/// 用 segno（一个独立的 QR 实现）产生的矩阵对 <see cref="QrEncoder"/> 做交叉校验
/// 并修正了 segno 在码字边界上的补位 bug。
/// </para>
/// <remarks>
/// 当比特流恰好结束在码字边界上时，segno 会补一整个多余的伪字节，因此参考矩阵
/// 是在修正那一行之后生成的。这里的每个向量也都经 zxing-cpp 解码并读回原文。
/// </remarks>
public class QrEncoderGoldenTests
{
    public static TheoryData<string, QrErrorCorrection, int, int, string> FullMatrices() => new()
    {
        { "2", QrErrorCorrection.Low, 1, 2, "" },
        { "8088880", QrErrorCorrection.Quartile, 1, 0, "" },
        { "230163662510914681030690813763363698013632896605837879564934999815721656830770320782658403407873297198328094889361310726", QrErrorCorrection.Quartile, 5, 0, "" },
        { ".", QrErrorCorrection.Medium, 1, 4, "" },
        { "IPVSBR1", QrErrorCorrection.Medium, 1, 0, "" },
        { "SB7*5M+.RTMZ98DBHUKQOKPCH4JTMNFPV7OTTN4E52 AE68K 5 GBU47U*M12AJ4E-32SSQ%Q6KMTF/B+:$HV/E12G:Y12B+SW+H26 7N.Z5ARNF-B63I1HG", QrErrorCorrection.Quartile, 7, 7, "" },
        { "~-", QrErrorCorrection.Low, 1, 1, "" },
        { "^kj T@y=eyC>\"uq|jmpGt VzY", QrErrorCorrection.High, 4, 4, "" },
    };

    [Theory]
    [MemberData(nameof(FullMatrices))]
    public void MatchesReferenceMatrix(string text, QrErrorCorrection ecc, int version, int mask, string expected)
    {
        var matrix = QrEncoder.Encode(text, ecc);

        Assert.Equal(version, matrix.Version);
        Assert.Equal(mask, matrix.Mask);
        Assert.Equal((version * 4) + 17, matrix.Size);
        Assert.Equal(expected, Flatten(matrix));
    }

