    [Theory]
    [MemberData(nameof(MatrixHashes))]
    public void MatchesReferenceMatrixHash(string text, QrErrorCorrection ecc, int version, int mask, string expectedHash)
    {
        var matrix = QrEncoder.Encode(text, ecc);

        Assert.Equal(version, matrix.Version);
        Assert.Equal(mask, matrix.Mask);
        Assert.Equal(expectedHash, Sha256(Flatten(matrix)));
    }

    private static string Flatten(QrMatrix matrix)
    {
        var builder = new StringBuilder(matrix.Size * matrix.Size);
        for (var y = 0; y < matrix.Size; y++)
        {
            for (var x = 0; x < matrix.Size; x++)
            {
                builder.Append(matrix[x, y] ? '1' : '0');
            }
        }

        return builder.ToString();
    }

    private static string Sha256(string value) =>
        Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
}
